function updateFreshness(){const badge=$('#odds-freshness');if(!state.oddsUpdatedAt){badge.textContent='Cotes : date de synchronisation indisponible';badge.className='freshness-badge stale';return}const updated=new Date(state.oddsUpdatedAt),next=new Date(updated.getTime()+state.refreshIntervalHours*3600000),now=new Date(),ageMinutes=Math.max(0,Math.floor((now-updated)/60000)),remainingMinutes=Math.max(0,Math.ceil((next-now)/60000)),age=ageMinutes<60?`${ageMinutes} min`:ageMinutes<1440?`${Math.floor(ageMinutes/60)} h ${ageMinutes%60} min`:`${Math.floor(ageMinutes/1440)} j`,remaining=remainingMinutes<60?`${remainingMinutes} min`:`${Math.floor(remainingMinutes/60)} h ${remainingMinutes%60} min`;badge.textContent=`Cotes mises à jour il y a ${age} · ${remainingMinutes?`prochaine synchronisation dans ${remaining}`:'actualisation attendue'}`;badge.className=`freshness-badge ${remainingMinutes?'fresh':'stale'}`}
