function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function settlePendingBets(results){let settled=0;for(const bet of state.history){if(bet.status!=='pending')continue;const status=settleBet(bet,results);if(status==='pending')continue;bet.status=status;bet.settledAt=new Date().toISOString();if(status==='won')state.bankroll+=bet.stake*bet.odds;settled++}if(settled)persist();return settled}
