async function loadLiveFixtures(){const source=$('#data-source');try{const response=await fetch(`data/fixtures.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();try{localStorage.setItem(FIXTURES_CACHE_KEY,JSON.stringify(data))}catch{}applyFixtureData(data)}catch(error){if(!state.liveMatches.length){source.innerHTML='<span class="source-dot fallback"></span> Calendrier de démonstration · flux officiel temporairement indisponible';render()}}}
function setActiveTab(tab,scroll=false){document.querySelectorAll('[data-view]').forEach(view=>view.classList.toggle('tab-hidden',view.dataset.view!==tab));document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));document.querySelectorAll('[data-mobile-target]').forEach(button=>button.classList.toggle('active',button.dataset.mobileTarget===tab));if(tab==='standings')details?.showStandings();if(scroll)document.querySelector(tab==='bankroll'?'#bankroll':tab==='standings'?'#standings':'#builder')?.scrollIntoView({behavior:'smooth'});const hash=tab==='bankroll'?'#bankroll':tab==='standings'?'#classements':'';if(typeof history!=='undefined')history.replaceState(null,'',hash||location.pathname+location.search);else location.hash=hash.slice(1)}
// Scores en direct : interroge ESPN toutes les 30 s pendant les matchs du moment, règle les paris dès le coup de sifflet final.
function liveCandidates(){const now=Date.now();return allMatches().filter(m=>!m.completed&&String(m.id).startsWith('espn-')&&LEAGUES[m.league]?.[4]&&now>kickoffAt(m)-10*60e3&&now<kickoffAt(m)+150*60e3)}
