function render(){renderDateNavigator();renderFilters();renderMatches();renderTicket();renderHistory();updateStats()}
$('#date-navigator').addEventListener('click',e=>{const b=e.target.closest('[data-date]');if(!b)return;state.dateFilter=b.dataset.date;state.revealed.clear();renderDateNavigator();renderFilters();renderMatches()});
function selectLeague(filter){state.filter=filter;state.revealed.clear();renderFilters();renderMatches()}
$('#filters').addEventListener('click',e=>{if(e.target.closest('[data-league-menu]')){renderLeagueMenu();$('#league-dialog').showModal();return}const b=e.target.closest('[data-filter]');if(b)selectLeague(state.filter===b.dataset.filter?'Tous':b.dataset.filter)});
$('#league-list').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;selectLeague(b.dataset.filter);$('#league-dialog').close();revealActive($('#filters'))});
$('#match-list').addEventListener('click',e=>{const more=e.target.closest('[data-details]');if(more){details?.openMatch(allMatches().find(match=>match.id===more.dataset.details));return}const team=e.target.closest('[data-team-id]');if(team){details?.openTeam({id:team.dataset.teamId,name:team.dataset.teamName,logo:team.dataset.teamLogo,league:team.dataset.league,matchId:team.dataset.teamMatch});return}const confidence=e.target.closest('[data-confidence]');if(confidence){showConfidence(allMatches().find(match=>match.id===confidence.dataset.confidence));return}const b=e.target.closest('[data-market]');if(b){flyToTicket(b);addSelection(b.dataset.match,b.dataset.market)}});
for(const rail of [$('#match-rail'),$('#match-strip')])rail.addEventListener('click',e=>{const link=e.target.closest('[data-rail]');if(!link)return;e.preventDefault();document.getElementById(`match-${link.dataset.rail}`)?.scrollIntoView({behavior:'smooth',block:'start'})});
$('#safe-picks-list').addEventListener('click',e=>{const b=e.target.closest('[data-safe-match]');if(b){flyToTicket(b);addSelection(b.dataset.safeMatch,b.dataset.safeMarket)}});
$('#ticket-items').addEventListener('click',e=>{if(e.target.dataset.remove!==undefined){state.ticket.splice(Number(e.target.dataset.remove),1);renderTicket()}});$('#stake').addEventListener('input',renderTicket);$('#target-odds').addEventListener('input',e=>{$('#target-output').textContent=Number(e.target.value).toFixed(2);renderTicket()});
$('#bet-mode').addEventListener('click',e=>{const button=e.target.closest('[data-bet-mode]');if(!button)return;state.betMode=button.dataset.betMode;renderTicket()});
function generate(){state.betMode='combined';state.ticket=optimizeCombo(visibleMatches().filter(match=>!match.completed),Number($('#target-odds').value),Number($('#selection-count').value),$('#risk-profile').value);renderTicket();const total=state.ticket.reduce((p,x)=>p*x.odd,1);toast(`Combiné ${$('#risk-profile').selectedOptions[0].text.toLowerCase()} : cote ${total.toFixed(2)} avec ${state.ticket.length} matchs`)}
$('#generate-combo').addEventListener('click',generate);$('#quick-combo').addEventListener('click',()=>{setActiveTab('matches',true);generate()});$('#clear-ticket').addEventListener('click',()=>{state.ticket=[];renderTicket()});
$('#share-combo').addEventListener('click',async()=>{if(!state.ticket.length)return;const total=state.ticket.reduce((product,item)=>product*item.odd,1),independent=state.betMode!=='combined',type=state.betMode==='single'?'Paris simples':state.betMode==='multiple'?'Paris multiples':`Combiné ${$('#risk-profile').selectedOptions[0].text}`,summary=independent?`${state.ticket.length} paris indépendants`:`Cote totale : ${total.toFixed(2)}`,text=`BetMaster · ${type}\n${state.ticket.map((item,index)=>`${index+1}. ${item.match}\n   ${item.label} @ ${item.odd.toFixed(2)}`).join('\n')}\n${summary}\nSimulation uniquement · 18+ · Jouez responsablement.`;try{if(navigator.share)await navigator.share({title:`Mon ticket BetMaster · ${type}`,text});else await navigator.clipboard.writeText(text);toast(navigator.share?'Ticket partagé':'Ticket copié dans le presse-papiers')}catch(error){if(error?.name!=='AbortError')toast('Impossible de partager ce ticket')}});
$('#place-bet').addEventListener('click',()=>{if(!accountAuthenticated){$('#account-dialog').showModal();toast('Connectez-vous ou créez un compte pour enregistrer ce pari');return}const stake=Number($('#stake').value),independent=state.betMode!=='combined',totalStake=stake*(independent?state.ticket.length:1);if(!state.ticket.length||stake<=0||totalStake>state.bankroll)return;const date=new Date().toISOString();state.bankroll-=totalStake;if(independent)state.history.unshift(...state.ticket.map(item=>({date,items:[item],stake,odds:item.odd,status:'pending',betType:state.betMode})));else{const odds=state.ticket.reduce((p,x)=>p*x.odd,1);state.history.unshift({date,items:[...state.ticket],stake,odds,status:'pending',betType:state.betMode})}const count=state.ticket.length;state.ticket=[];persist();render();setActiveTab('bankroll',true);toast(independent?`${count} paris simples ajoutés à votre historique`:'Pari virtuel ajouté à votre historique')});
$('#open-add-match').addEventListener('click',()=>{const dialog=$('#match-dialog');dialog.querySelector('[name=date]').value=isoDate(0);dialog.showModal()});$('#match-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const d=Object.fromEntries(new FormData(e.target));state.customMatches.push({id:`custom-${Date.now()}`,date:d.date,priority:50,league:d.league,time:d.time,home:d.home,away:d.away,homeGoals:Number(d.homeGoals),awayGoals:Number(d.awayGoals),odds:{home:Number(d.oddHome),draw:Number(d.oddDraw),away:Number(d.oddAway),over:1.85,btts:1.80}});persist();render();toast('Match analysé et ajouté')});
$('#edit-bankroll').addEventListener('click',()=>{const d=$('#bankroll-dialog');d.querySelector('[name=amount]').value=state.bankroll;d.showModal()});$('#bankroll-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;state.bankroll=Number(new FormData(e.target).get('amount'));state.initial=state.bankroll;persist();render();toast('Bankroll mise à jour')});
const syncThemeColor=()=>{const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=document.documentElement.classList.contains('light')?'#F2F4F0':'#0A0C0B'};
$('#theme-toggle').addEventListener('click',()=>{document.documentElement.classList.toggle('light');localStorage.setItem('betmaster-theme',document.documentElement.classList.contains('light')?'light':'dark');syncThemeColor();render()});if(localStorage.getItem('betmaster-theme')==='light')document.documentElement.classList.add('light');syncThemeColor();
$('#hero-confidence').addEventListener('click',()=>showConfidence());$('#open-help').addEventListener('click',()=>$('#help-dialog').showModal());document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$('#refresh-fixtures').addEventListener('click',()=>{state.liveMatches=[];$('#data-source').innerHTML='<span class="source-dot loading"></span> Actualisation…';loadLiveFixtures()});
// Pied de page : navigation, pages d'information (avec ancre de section) et année.
document.querySelectorAll('[data-open-dialog]').forEach(button=>button.addEventListener('click',()=>{const dialog=$(`#${button.dataset.openDialog}`);dialog.showModal();const section=button.dataset.section&&dialog.querySelector(`#${button.dataset.section}`);if(section)section.scrollIntoView({block:'start'});else dialog.scrollTop=0}));
document.querySelectorAll('[data-footer-nav]').forEach(button=>button.addEventListener('click',()=>{const target=button.dataset.footerNav;setActiveTab(['bankroll','standings'].includes(target)?target:'matches');document.querySelector(target==='bankroll'?'#bankroll':target==='standings'?'#standings':target==='builder'?'#builder':'#matches')?.scrollIntoView({behavior:'smooth'})}));
document.querySelector('.tabs').addEventListener('click',e=>{const button=e.target.closest('[data-tab]');if(button)setActiveTab(button.dataset.tab,true)});document.querySelectorAll('[data-open-tab]').forEach(button=>button.addEventListener('click',()=>setActiveTab(button.dataset.openTab,true)));
document.querySelector('.mobile-nav').addEventListener('click',e=>{const button=e.target.closest('[data-mobile-target]');if(!button)return;const target=button.dataset.mobileTarget;setActiveTab(['bankroll','standings'].includes(target)?target:'matches');document.querySelectorAll('[data-mobile-target]').forEach(item=>item.classList.toggle('active',item===button));document.querySelector(target==='bankroll'?'#bankroll':target==='standings'?'#standings':target==='builder'?'#builder':'#matches')?.scrollIntoView({behavior:'smooth'});});
try{const cached=JSON.parse(localStorage.getItem(FIXTURES_CACHE_KEY)||'null');if(cached)applyFixtureData(cached,true)}catch{}setActiveTab(location.hash==='#bankroll'?'bankroll':location.hash==='#classements'?'standings':'matches');render();if(typeof window!=='undefined'){$('#footer-year').textContent=new Date().getFullYear();history.scrollRestoration='manual';if(location.hash!=='#bankroll')scrollTo({top:0,behavior:'instant'});$('#match-list').classList.add('reveal');setInterval(tickCountdowns,1000);setInterval(pollLive,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollLive()});setupScroller($('#date-navigator'));setupScroller($('#filters'));setupScroller($('#standings-leagues'));import('./details.js?v=fiches-6').then(module=>{details=module.initDetails({allMatches,logoTag,leagueLogoUrl,LEAGUES,isLive,kickoffAt,state,toast,updateScrollers});if(location.hash==='#classements')details.showStandings()}).catch(error=>console.error('Fiches indisponibles',error));addEventListener('resize',updateScrollers);requestAnimationFrame(()=>{revealActive($('#date-navigator'),false);updateScrollers()});countUp();setTimeout(pollLive,1500);setTimeout(()=>document.documentElement.classList.remove('intro'),2000);loadLiveFixtures();setInterval(loadLiveFixtures,5*60*1000);setInterval(updateFreshness,60000);import('./account.js?v=accounts-5').then(({initAccountSync})=>initAccountSync({getState:userStatePayload,applyState:applySyncedState,resetState:resetSyncedState,registerCloudSave:save=>{cloudSave=save},onAuthChange:authenticated=>{accountAuthenticated=authenticated;renderTicket()},toast})).catch(error=>{console.error('Compte indisponible',error);$('#account-label').textContent='Compte indisponible'})}
